import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI 協議（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/uri-protocol.md","filePath":"zh-HK/user-guide/uri-protocol.md","lastUpdated":1785993908000}'),d={name:"zh-HK/user-guide/uri-protocol.md"};function c(s,e,l,n,i,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="uri-協議-lertaro" tabindex="-1">URI 協議（lertaro://） <a class="header-anchor" href="#uri-協議-lertaro" aria-label="Permalink to &quot;URI 協議（lertaro://）&quot;">​</a></h1><p>Lertaro 會自動把自己註冊為 <code>lertaro://</code> 鏈接的處理程式——不需要額外的安裝步驟，第一次運行時就會自動完成註冊。這樣任何能打開鏈接的東西（瀏覽器、捷徑、別的程式、腳本）都能直接跳到 Lertaro 的某個具體位置，而不是只能靠熱鍵觸發。</p><p>如果 Lertaro 還沒運行，打開一個 <code>lertaro://</code> 鏈接會先啓動它，再執行這個鏈接指向的操作。如果已經在運行，正在運行的那個實例會直接處理這個鏈接——不會再啓動第二份處理程序。</p><h2 id="支援的鏈接" tabindex="-1">支援的鏈接 <a class="header-anchor" href="#支援的鏈接" aria-label="Permalink to &quot;支援的鏈接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>鏈接</th><th>作用</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>激活快速搜尋視窗——效果和用熱鍵呼出它一樣。</td></tr><tr><td><code>lertaro://search/[關鍵詞]</code></td><td>激活快速搜尋視窗，並預填 <code>[關鍵詞]</code>。</td></tr><tr><td><code>lertaro://fullsearch/[關鍵詞]</code></td><td>打開完整搜尋視窗，並預填 <code>[關鍵詞]</code>。</td></tr><tr><td><code>lertaro://settings/page/[分區]</code></td><td>打開設定視窗，並切到指定的頂層分區。</td></tr><tr><td><code>lertaro://settings/entry/[序號]</code></td><td>打開設定視窗，並直接跳轉到某一項具體設定，並高亮顯示。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>第一個會激活快速搜尋視窗，並已經用&quot;report&quot;過濾好；第二個會直接打開設定視窗的&quot;外觀&quot;頁。</p><p><code>[分區]</code> 對應側邊欄頂層的某一項：<code>Service</code>、<code>Index</code>、<code>General</code>、<code>Appearance</code>、<code>Hotkeys</code>、 <code>Plugins</code>、<code>Favorites</code>、<code>History</code>、<code>QuickPanel</code>、<code>About</code>——不區分大小寫。</p><p><code>[序號]</code> 不是給人手動輸入用的——它是<a href="./instant-answers.html">設定搜尋</a>在你選中某項設定結果時自己生成的一個數字，選中結果會自動帶上這個序號，原樣跳轉回那一項設定。這個序號在重啓之間並不穩定，不要指望某個具體數字每次都對應同一項設定。</p><h2 id="無法識別的鏈接" tabindex="-1">無法識別的鏈接 <a class="header-anchor" href="#無法識別的鏈接" aria-label="Permalink to &quot;無法識別的鏈接&quot;">​</a></h2><p>任何匹配不上已知路由的鏈接——打錯了字、分區不存在、<code>lertaro://</code> 後面跟了一堆亂七八糟的內容——都會被直接忽略。由於任何網站或程式都能在你不知情的情況下調起這個協議，一個錯誤或異常的鏈接不應該產生任何出人意料的效果；這類情況只會記進日誌方便你自己排查，除此之外什麼都不會發生。</p>`,11)])])}const _=t(d,[["render",c]]);export{u as __pageData,_ as default};
